        var next = new Image();
        next.decoding = 'async';
        next.onload = function() {
          var decoded = next.decode ? next.decode().catch(function(){}) : Promise.resolve();
          decoded.then(function(){ image.src=source; image.removeAttribute('data-jdc-poster-src'); });
        };
        next.onerror = function(){ image.__jdcLoadingPoster=false; };
        next.src=source;
