    var headerRow = el("div", "jdc-mirror-onepage-header-row");
    headerRow.id = "jdc-mirror-onepage-header-row";
    headerRow.setAttribute("data-jdc-onepage-header", "pinned-row-78");
    var brandLink = el("a", "jdc-mirror-onepage-brand", "JDC");
    brandLink.href = "/";
